INSERT INTO `william_system_message` VALUES (857, '轉生技能點數重置成功 10秒後將會斷線。', '重置轉生技能給予提示');
INSERT INTO `william_system_message` VALUES (6499, '天賦點數不足。', '升級天賦技能點數不足提示');
INSERT INTO `william_system_message` VALUES (6500, '金剛護體', '王族(1) - 金剛護體: 被玩家攻擊時有機率[無敵]1秒，每加1點發動率增加1%');
INSERT INTO `william_system_message` VALUES (6501, '屬性之光', '王族(2) - 屬性之光: 增加武器屬性卷軸發動率，每加1點發動率增加1%');
INSERT INTO `william_system_message` VALUES (6502, '榮耀治愈', '王族(3) - 榮耀治愈: 受到治愈增加 每+1點被補血量+2% 以此類推');
INSERT INTO `william_system_message` VALUES (6503, '強化衝暈', '騎士(1) - 強化衝暈: 強化騎士衝擊之暈魔法命中率.每加1點命中率增加1%');
INSERT INTO `william_system_message` VALUES (6504, '狂暴致命', '騎士(2) - 狂暴致命: 血量低於30%有機率打出最高3倍普攻傷害，每加1點發動率+1%(傷害點數算法.最大血量/目前血量=傷害倍數)');
INSERT INTO `william_system_message` VALUES (6505, '神盾護體', '騎士(3) - 神盾護體: 面對正前方三個面向的攻擊 機率向發動30%減傷.每加1點發動率增加1%');
INSERT INTO `william_system_message` VALUES (6506, '神聖祝福', '妖精(1) - 神聖祝福: 恢復類法術效果增加/魂體回魔增加，每加1點補血效果增加5%回魔量+2滴');
INSERT INTO `william_system_message` VALUES (6507, '吞噬魔力', '妖精(2) - 吞噬魔力: 有機率扣除對方魔力2%.每加1點發動率增加1%');
INSERT INTO `william_system_message` VALUES (6508, '傷害擊殺', '妖精(3) - 傷害擊殺: 機率無視玩家迴避率，每加1點發動率加2%');
INSERT INTO `william_system_message` VALUES (6509, '致命一擊', '法師(1) - 致命一擊: 施放傷害魔法有機率無視對方抗魔，每加1點發動率+2%');
INSERT INTO `william_system_message` VALUES (6510, '療癒風暴', '法師(2) - 療癒風暴: 機率固定10% 天賦加一點 補血量增加10%，點滿5點就是+50%');
INSERT INTO `william_system_message` VALUES (6511, '血之聖光', '法師(3) - 血之聖光: 增加血量，每加1點血量增加400');
INSERT INTO `william_system_message` VALUES (6512, '背部襲擊', '黑妖(1) - 背部襲擊: 在目標敵人後三個面向攻擊，有機率造成1.5倍高傷害，每加1點發動率增加1%');
INSERT INTO `william_system_message` VALUES (6513, '附加劇毒', '黑妖(2) - 附加劇毒: 強化附加劇毒.每加1點每秒中毒傷害增加15滴');
INSERT INTO `william_system_message` VALUES (6514, '神之跳躍', '黑妖(3) - 神之跳躍: 有機率閃避所有物理傷害.每加1點閃避機率增加1%');
INSERT INTO `william_system_message` VALUES (6515, '屠宰擊殺', '龍騎(1) - 屠宰擊殺: 屠宰者隨機扣目標當前生命3%(限鎖鏈劍)對怪物固定扣HP200，每加1點發動機率增加1%');
INSERT INTO `william_system_message` VALUES (6516, '乾坤挪移', '龍騎(2) - 乾坤挪移: 將目前傷害100%轉為自身吸血.每加1點發動機率增加2%');
INSERT INTO `william_system_message` VALUES (6517, '強之護鎧', '龍騎(3) - 強之護鎧: 強化自身減傷.每加1點受到的所有傷害減免1%');
INSERT INTO `william_system_message` VALUES (6518, '毀壞之身', '幻術(1) - 毀壞之身: 增加骷髏毀壞命中率.每加1點命中機率增加1%');
INSERT INTO `william_system_message` VALUES (6519, '心靈破壞', '幻術(2) - 心靈破壞: 增加心靈破壞的傷害(限奇古獸).增加1點耗魔增加15點');
INSERT INTO `william_system_message` VALUES (6520, '血之聖光', '幻術(3) - 血之聖光: 增加血量，每加1點血量增加400');
INSERT INTO `william_system_message` VALUES (6521, '冰封心智', '戰士(1) - 冰封心智: 攻擊有機率讓對方無法攻擊2秒，每加1點發動機率增加1%');
INSERT INTO `william_system_message` VALUES (6522, '魔傷其發', '戰士(2) - 魔傷其發: 增加武器的魔法傷害.每加1點魔法武器傷害增加3%');
INSERT INTO `william_system_message` VALUES (6523, '殺氣擊斃', '戰士(3) - 殺氣擊斃: 目標血量低於45%.自身攻擊提升.每加1點整體攻擊力提升3%');
INSERT INTO `william_system_message` VALUES (8018, '發動天賦技能 金剛護體 無敵1秒。', '王族(1) - 金剛護體-發動時提示');
INSERT INTO `william_system_message` VALUES (8013, '發動天賦技能 神之跳躍 閃避所有物理傷害。', '黑妖(3) - 神之跳躍-發動時提示');
INSERT INTO `william_system_message` VALUES (8014, '發動天賦技能 吞噬魔力 扣除對方2%魔力。', '妖精(2) - 吞噬魔力-發動時提示');
INSERT INTO `william_system_message` VALUES (8040, '受到戰士天賦技能 冰封心智 效果影響，暫無法攻擊2秒。', '戰士(1) - 冰封心智-發動時被攻擊者提示');
INSERT INTO `william_system_message` VALUES (8041, '發動天賦技能 致命一擊 無視對方抗魔。', '法師(1) - 致命一擊-發動時提示');
INSERT INTO `william_system_message` VALUES (8042, '發動天賦技能 傷害擊殺 無視玩家迴避率。', '妖精(3) - 傷害擊殺-發動時提示-對玩家');
INSERT INTO `william_system_message` VALUES (8044, '發動天賦技能 背部襲擊 造成1.5倍傷害。', '黑妖(1) - 背部襲擊-發動時提示');
INSERT INTO `william_system_message` VALUES (8045, '發動天賦技能 神盾護體 減少30%傷害。', '騎士(3) - 神盾護體-發動時提示');
