  `level` int(11) UNSIGNED NOT NULL DEFAULT 0,
  `HighLevel` int(11) UNSIGNED NOT NULL DEFAULT 0,
  `Exp` bigint(10) UNSIGNED NOT NULL DEFAULT 0,
  `MaxHp` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `CurHp` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `MaxMp` int(10) NOT NULL DEFAULT 0,
  `CurMp` int(10) NOT NULL DEFAULT 0,
  `Ac` int(10) NOT NULL DEFAULT 0,
  `Str` int(3) NOT NULL DEFAULT 0,
  `Con` int(3) NOT NULL DEFAULT 0,
  `Dex` int(3) NOT NULL DEFAULT 0,
  `Cha` int(3) NOT NULL DEFAULT 0,
  `Intel` int(3) NOT NULL DEFAULT 0,
  `Wis` int(3) NOT NULL DEFAULT 0,
  `Status` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `Class` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `Sex` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `Type` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `Heading` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `LocX` int(11) UNSIGNED NOT NULL DEFAULT 0,
  `LocY` int(11) UNSIGNED NOT NULL DEFAULT 0,
  `MapID` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `Food` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `Lawful` int(10) NOT NULL DEFAULT 0,
  `Title` varchar(35) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '',
  `ClanID` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `Clanname` varchar(45) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '',
  `ClanRank` int(3) NOT NULL DEFAULT 0,
  `rejoin_clan_time` datetime NULL DEFAULT NULL,
  `BonusStatus` int(10) NOT NULL DEFAULT 0,
  `ElixirStatus` int(10) NOT NULL DEFAULT 0,
  `ElfAttr` int(10) NOT NULL DEFAULT 0,
  `ElfAttrResetCount` int(10) NOT NULL DEFAULT 0 COMMENT '精靈遺忘屬性技能次數',
  `PKcount` int(10) NOT NULL DEFAULT 0,
  `PkCountForElf` int(10) NOT NULL DEFAULT 0,
  `ExpRes` int(10) NOT NULL DEFAULT 0,
  `PartnerID` int(10) NOT NULL DEFAULT 0,
  `OnlineStatus` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `HomeTownID` int(10) NOT NULL DEFAULT 0,
  `Contribution` int(10) NOT NULL DEFAULT 0,
  `Pay` int(10) NOT NULL DEFAULT 0,
  `HellTime` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `Banned` tinyint(1) UNSIGNED NOT NULL DEFAULT 0,
  `Karma` int(10) NOT NULL DEFAULT 0,
  `LastPk` datetime NULL DEFAULT NULL,
  `LastPkForElf` datetime NULL DEFAULT NULL,
  `DeleteTime` datetime NULL DEFAULT NULL,
  `OriginalStr` int(3) NOT NULL DEFAULT 0,
  `OriginalCon` int(3) NOT NULL DEFAULT 0,
  `OriginalDex` int(3) NOT NULL DEFAULT 0,
  `OriginalCha` int(3) NULL DEFAULT 0,
  `OriginalInt` int(3) NOT NULL DEFAULT 0,
  `OriginalWis` int(3) NOT NULL DEFAULT 0,
  `CreateTime` int(10) NOT NULL DEFAULT 20090901,
  `ClanMemberNotes` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '',
  `LastLogin` datetime NULL DEFAULT NULL,
  `MeteLevel` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `ReincarnationSkillCount` int(10) NOT NULL DEFAULT 0 COMMENT '轉生天賦點數',
  `PunishTime` datetime NULL DEFAULT NULL,
  `BanError` int(10) NULL DEFAULT 0,
  `InputBanError` int(10) NULL DEFAULT 0,
  `SpeedError` int(10) NULL DEFAULT 0,
  `RocksPrisonTime` int(10) NULL DEFAULT NULL,
  `IvorytowerTime` int(10) NULL DEFAULT NULL,
  `LastabardTime` int(10) NULL DEFAULT NULL,
  `DragonValleyTime` int(10) NULL DEFAULT NULL,
  `MazuTime` int(10) NULL DEFAULT 0,
  `AI_TIMES` int(10) NULL DEFAULT NULL COMMENT '驗證計時',
  `TamEndTime` datetime NULL DEFAULT NULL,
  `Mark_Count` int(10) NOT NULL DEFAULT 60,
  `OnlineGiftIndex` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `OnlineGiftWiatEnd` smallint(1) UNSIGNED NOT NULL DEFAULT 0,
  `VipStartTime` timestamp NULL DEFAULT NULL,
  `VipEndTime` timestamp NULL DEFAULT NULL,
  `VipLevel` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `OtherStatus` int(10) NOT NULL DEFAULT 0,
  `AddPoint` int(10) NOT NULL DEFAULT 0,
  `DelPoint` int(10) NOT NULL DEFAULT 0,
  `RingsExpansion` tinyint(1) NULL DEFAULT 0 COMMENT '戒指欄位擴充紀錄 (1=左邊戒指 2=右邊戒指 3=左右戒指)',
  `EarringsExpansion` tinyint(1) NULL DEFAULT 0 COMMENT '耳環欄位擴充紀錄',
  `jianjiakz` tinyint(1) NULL DEFAULT NULL COMMENT '肩甲擴充記錄',
  `huizhangkz` tinyint(1) NULL DEFAULT NULL COMMENT '徽章擴充記錄',
  `EquipmentIndexAmulet` tinyint(1) NULL DEFAULT 0 COMMENT '文符欄位擴充記錄',
  `RedblueReward` tinyint(1) NULL DEFAULT 0 COMMENT '對戰獎勵次數',
  `timemap1` int(10) NULL DEFAULT NULL,
  `timemap2` int(10) NULL DEFAULT NULL,
  `timemap3` int(10) NULL DEFAULT NULL,
  `timemap4` int(10) NULL DEFAULT NULL,
  PRIMARY KEY (`objid`) USING BTREE,
  INDEX `key_id`(`account_name`, `char_name`) USING BTREE
) ENGINE = MyISAM CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

