  PRIMARY KEY (`number`, `buff_id`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 268576640 CHARACTER SET = euckr COLLATE = euckr_korean_ci ROW_FORMAT = Dynamic;

