-- ----------------------------
-- Table structure for craft
-- ----------------------------
DROP TABLE IF EXISTS `craft`;
CREATE TABLE `craft`  (
  `id` int(10) NOT NULL,
  `note` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT '',
  `check_note` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT '',
  `craft_nameid` int(10) NOT NULL DEFAULT 0,
  `craft_itemid` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '',
  `craft_count` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '',
  `craft_enchant` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '',
  `material` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '',
  `material_count` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '',
  `material_enchant` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '',
  `material_bless` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '',
  `material_attrId` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '0' COMMENT '材料屬性類型，需跟material_attrLv一起設',
  `material_attrLv` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '' COMMENT '材料屬性等級，需跟material_attrId一起設',
  `class_limit` int(10) NOT NULL DEFAULT 0 COMMENT '可製作的角色職業(不能製作的職業無法顯示出製作清單)(不判斷:0 王族:1 騎士:2 精靈:4 法師:8 黑妖:16 龍騎:32 幻術:64 戰士:128)',
  `min_level` int(10) NOT NULL DEFAULT 1,
  `max_level` int(10) NOT NULL DEFAULT 99,
  `min_lawful` int(10) NOT NULL DEFAULT -32768,
  `max_lawful` int(10) NOT NULL DEFAULT 32767,
  `min_karma` int(10) NOT NULL DEFAULT -2147483648,
  `max_karma` int(10) NOT NULL DEFAULT 2147483647,
  `max_count` int(10) NOT NULL DEFAULT 100 COMMENT '默認100',
  `change` int(10) NOT NULL DEFAULT 100 COMMENT '打造機率(100%)',
  `add_chance_itemid` int(10) NOT NULL DEFAULT 0 COMMENT '加增機率的道具(只支持一般屬性,祝福跟詛咒不支持)',
  `add_chance_itemid_count` int(10) NOT NULL DEFAULT 0 COMMENT '加增機率的道具數量',
  `fail_itemid` int(10) NOT NULL DEFAULT 0 COMMENT '失敗時退回的道具',
  `fail_item_count` int(10) NOT NULL DEFAULT 0 COMMENT '失敗時退回的道具數量',
  `fail_item_enchant` int(10) NOT NULL DEFAULT 0 COMMENT '失敗時退回的道具加成',
  `perfect_chance` int(1) NOT NULL DEFAULT 0 COMMENT '大成功機率(必須跟大成功道具一起設)(不判斷都要設0)',
  `perfect_itemid` int(10) NOT NULL DEFAULT 0 COMMENT '大成功道具(必須跟大成功機率一起設)(不判斷都要設0)',
  `perfect_item_count` int(10) NOT NULL DEFAULT 0 COMMENT '大成功道具數量(不判斷要設0)',
  `perfect_item_enchant` int(10) NOT NULL DEFAULT 0 COMMENT '大成功道具加成(不判斷要設0)',
  `showworld` int(1) NOT NULL DEFAULT 0 COMMENT '玩家打造道具成功是否公告(0=不公告，1=公告)',
  `ignoreItemId` int(10) NOT NULL DEFAULT 0 COMMENT '玩家身上已有此編號道具將不能在製作(0=不判斷)',
  `craft_attrId` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '0' COMMENT '屬性類型(官服是:1火靈/2水靈/3風靈/4地靈)，其它自製的不支持顯示，需跟craft_attrLv一起設',
  `craft_attrLv` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '0' COMMENT '屬性等級，需跟craft_attrId一起設',
  `fail_item_attrId` int(2) NOT NULL DEFAULT 0 COMMENT '失敗時退回的道具屬性類型，需跟fail_item_attrLv一起設',
  `fail_item_attrLv` int(2) NOT NULL DEFAULT 0 COMMENT '失敗時退回的道具屬性等級，需跟fail_item_attrId一起設',
  PRIMARY KEY (`id`, `material_enchant`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of craft
-- ----------------------------

