  `price` int(10) NOT NULL DEFAULT 500000 COMMENT '價格(1/100的價格 遊戲中 會在*100)',
  `sellcount` int(10) UNSIGNED NOT NULL DEFAULT 1 COMMENT '最大賣出數量',
  `buycount` int(10) NOT NULL DEFAULT 0 COMMENT '最大買入數量(核心已取消此功能)',
  `enchantlvl` int(10) NOT NULL DEFAULT 0,
  `note` varchar(45) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 269 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

