  `get_item_id` int(10) NULL DEFAULT NULL,
  `name` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT '' COMMENT '物品名稱',
  `randomint` int(10) NOT NULL DEFAULT 1000000 COMMENT '比對用機率',
  `random` int(10) NOT NULL DEFAULT 1000 COMMENT '機率',
  `min_count` int(10) NOT NULL DEFAULT 1 COMMENT '給予數量(最少)',
  `max_count` int(10) NOT NULL DEFAULT 1 COMMENT '物品量數(最多)',
