-- ----------------------------
-- Table structure for etcitem_doll_power
-- ----------------------------
DROP TABLE IF EXISTS `etcitem_doll_power`;
CREATE TABLE `etcitem_doll_power`  (
  `id` int(10) NOT NULL AUTO_INCREMENT,
  `classname` varchar(45) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '0',
  `type1` int(10) NOT NULL DEFAULT 0,
  `type2` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `type3` int(10) NOT NULL DEFAULT 0,
  `注解` varchar(150) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT '' COMMENT '注解-說明',
  `note` varchar(150) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT '' COMMENT '能力描述自設',
  `ac` int(10) NOT NULL DEFAULT 0 COMMENT '顯示用-防禦+type1',
  `str` int(10) NOT NULL DEFAULT 0 COMMENT '顯示用-力量+type1',
  `dex` int(10) NOT NULL DEFAULT 0 COMMENT '顯示用-敏捷+type1',
  `con` int(10) NOT NULL DEFAULT 0 COMMENT '顯示用-體質+type1',
  `int` int(10) NOT NULL DEFAULT 0 COMMENT '顯示用-智力+type1',
  `wis` int(10) NOT NULL DEFAULT 0 COMMENT '顯示用-精神+type1',
  `cha` int(10) NOT NULL DEFAULT 0 COMMENT '顯示用-魅力+type1',
  `hp` int(10) NOT NULL DEFAULT 0 COMMENT '顯示用-體力上限+type1',
  `mp` int(10) NOT NULL DEFAULT 0 COMMENT '顯示用-魔力上限+type1',
  `hpr` int(10) NOT NULL DEFAULT 0 COMMENT '顯示用-回血+type1',
  `mpr` int(10) NOT NULL DEFAULT 0 COMMENT '顯示用-魔回+type1',
  `mr` int(10) NOT NULL DEFAULT 0 COMMENT '顯示用-魔防+type1',
  `sp` int(10) NOT NULL DEFAULT 0 COMMENT '顯示用-魔攻+type1',
  `dmg` int(10) NOT NULL DEFAULT 0 COMMENT '顯示用-近戰傷害+type1',
  `hit` int(10) NOT NULL DEFAULT 0 COMMENT '顯示用-近戰命中+type1',
  `bowdmg` int(10) NOT NULL DEFAULT 0 COMMENT '顯示用-遠程傷害+type1',
  `bowhit` int(10) NOT NULL DEFAULT 0 COMMENT '顯示用-遠程命中+type1',
  `alldmg_r` int(10) NOT NULL DEFAULT 0 COMMENT '顯示用-傷害減免+type1',
  `exp` int(10) NOT NULL DEFAULT 0 COMMENT '顯示用-狩獵經驗值+type1',
  `weight` int(10) NOT NULL DEFAULT 0 COMMENT '顯示用-負重增加(%)+type2',
  `weight_r` int(10) NOT NULL DEFAULT 0 COMMENT '顯示用-增加負重(+)+type1',
  `fire` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '顯示用-火屬性+type1',
  `wind` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '顯示用-風屬性+type1',
  `earth` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '顯示用-地屬性+type1',
  `water` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '顯示用-水屬性+type1',
  `技術耐性` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '顯示用-技術耐性+type1',
  `精靈耐性` int(10) NOT NULL DEFAULT 0 COMMENT '顯示用-精靈耐性+type1',
  `龍屬耐性` int(10) NOT NULL DEFAULT 0 COMMENT '顯示用-龍屬耐性+type1',
  `恐怖耐性` int(10) NOT NULL DEFAULT 0 COMMENT '顯示用-恐怖耐性+type1',
  `全部耐性` int(10) NOT NULL DEFAULT 0 COMMENT '顯示用-全部耐性+type1',
  `技術命中` int(10) NOT NULL DEFAULT 0 COMMENT '顯示用-技術命中+type1',
  `精靈命中` int(10) NOT NULL DEFAULT 0 COMMENT '顯示用-精靈命中+type1',
  `龍屬命中` int(10) NOT NULL DEFAULT 0 COMMENT '顯示用-龍屬命中+type1',
  `恐怖命中` int(10) NOT NULL DEFAULT 0 COMMENT '顯示用-恐怖命中+type1',
  `全部命中` int(10) NOT NULL DEFAULT 0 COMMENT '顯示用-全部命中+type1',
  `haste` int(10) NOT NULL DEFAULT 0 COMMENT '顯示用-加速效果 1=顯示',
  `stunlv` int(10) NOT NULL DEFAULT 0 COMMENT '顯示用-昏迷等級+type1',
  `breaklv` int(10) NOT NULL DEFAULT 0 COMMENT '顯示用-破壞盔甲等級+',
  `foeslayer` int(10) NOT NULL DEFAULT 0 COMMENT '顯示用-屠宰者階段別傷害+',
  `titanhp` int(10) NOT NULL DEFAULT 0 COMMENT '顯示用-泰坦系列技能發動 HP 區間增加+',
  `PVP傷害` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT 'PVP傷害',
  `PVP減免` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT 'PVP傷害',
  `殷海薩祝` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT 'PVP傷害',
  PRIMARY KEY (`id`) USING BTREE,
