DROP TABLE IF EXISTS `extra_item_integration`;
CREATE TABLE `extra_item_integration`  (
  `id` int(10) NOT NULL AUTO_INCREMENT,
  `item_id` int(10) NULL DEFAULT NULL,
  `name` char(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `checkClass` int(1) NOT NULL DEFAULT 0,
  `level` int(2) NOT NULL DEFAULT 0,
  `needCount` int(5) NOT NULL DEFAULT 0,
  `Integration_ID` int(10) NOT NULL DEFAULT 0,
  `Integration_count` int(10) NOT NULL DEFAULT 1,
  `random` varchar(1000) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '100',
  `materials` varchar(1000) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `counts` varchar(1000) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
