  `msg_falue` varchar(1000) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `falue_Del` int(6) NOT NULL DEFAULT 0 COMMENT '失敗是否刪除道具 (0否1是)',
  `gfxId` int(6) NOT NULL DEFAULT 14035,
