-- ----------------------------
-- Table structure for extra_item_steal
-- ----------------------------
DROP TABLE IF EXISTS `extra_item_steal`;
CREATE TABLE `extra_item_steal`  (
  `item_id` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '道具編號',
  `note` char(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '註解說明',
  `steal_chance` int(5) UNSIGNED NOT NULL DEFAULT 0 COMMENT '死亡被奪取機率',
  `min_steal_count` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '最低被奪取數量',
  `max_steal_count` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '最高被奪取數量',
  `is_broadcast` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '被奪取道具是否廣播',
  `drop_on_floor` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '被奪取道具是否掉落在地面 (1=掉地面, 0=掉在攻擊者身上)',
  `anti_steal_item_id` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '防止奪取道具編號',
  `level` int(5) NULL DEFAULT 0 COMMENT '等級以上不會被搶奪',
  `mete_level` int(5) NULL DEFAULT 0 COMMENT '轉生次數',
