-- ----------------------------
DROP TABLE IF EXISTS `extra_weapon_boss`;
CREATE TABLE `extra_weapon_boss`  (
  `item_id` int(10) UNSIGNED NOT NULL,
  `boss_lv` int(10) NOT NULL DEFAULT 1,
  `boss_name` varchar(45) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL,
  `success_random` int(10) NOT NULL DEFAULT -1 COMMENT '強化成功機率',
  `max_use_time` int(10) NOT NULL DEFAULT 60 COMMENT '附加在武器上的魔法時間 (單位:秒)',
  `success_msg` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '加持成功訊息',
  `failure_msg` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '加持失敗訊息',
  `probability` int(10) UNSIGNED NOT NULL DEFAULT 5 COMMENT '效果發動機率',
  `isLongRange` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否對遠距武器(弓or鐵手甲) 發動率除以二 (0 = 否, 1 = 是)',
  `fixDamage` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '固定傷害',
  `randomDamage` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '隨機傷害',
  `doubleDmgValue` double(10, 1) UNSIGNED NOT NULL DEFAULT 0.0 COMMENT '暴擊倍率',
  `gfxId` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '發動特效編號',
  `gfxIdTarget` int(1) UNSIGNED NOT NULL DEFAULT 1 COMMENT '目標對象 (0 = 自身, 1 = 對方)',
  `arrowType` int(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '飛行效果 (1 = 開啟, 0 = 關閉)',
  `effectId` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '額外技能skill編號',
  `effectTime` int(10) UNSIGNED NOT NULL DEFAULT 3 COMMENT '額外技能持續效果時間 (單位:秒)',
  `negativeId` int(10) NOT NULL DEFAULT 0 COMMENT '新增額外負面技能類型(不受距離限制)',
  `negativeTime` int(10) NOT NULL DEFAULT 0 COMMENT '新增額外負面技能時間(不受距離限制) (單位:秒)',
  `attr` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '傷害附加屬性 (0:無, 1:地, 2:火, 4:水, 8:風, 16:光)',
  `hpAbsorb` int(10) NOT NULL DEFAULT 0 COMMENT '吸血量',
  `mpAbsorb` int(10) NOT NULL DEFAULT 0 COMMENT '吸魔量',
  `type_remove_weapon` int(1) NOT NULL DEFAULT 0,
  `type_remove_armor` int(5) NOT NULL DEFAULT 0,
  PRIMARY KEY (`item_id`, `boss_lv`) USING BTREE
) ENGINE = MyISAM CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

