  `probability` int(10) UNSIGNED NOT NULL DEFAULT 5 COMMENT '效果發動機率',
  `isLongRange` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否對遠距武器(弓or鐵手甲) 發動率除以二 (0 = 否, 1 = 是)',
  `fixDamage` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '固定傷害',
  `randomDamage` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '隨機傷害',
  `doubleDmgValue` double(10, 1) UNSIGNED NOT NULL DEFAULT 0.0 COMMENT '暴擊倍率',
  `gfxId` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '發動特效編號',
  `gfxIdTarget` tinyint(1) UNSIGNED NOT NULL DEFAULT 1 COMMENT '目標對象 (0 = 自身, 1 = 對方)',
  `gfxIdOtherLoc` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '' COMMENT '額外發動特效座標 (請輸入座標格式) (例:-2/-2, 2/-2, 2/2, -2/2)',
  `area` tinyint(3) NOT NULL DEFAULT 0 COMMENT '幾格範圍傷害',
  `arrowType` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '飛行效果 (0 = 關閉, 1 = 開啟)',
  `effectId` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '額外技能skill編號',
  `effectTime` int(10) UNSIGNED NOT NULL DEFAULT 3 COMMENT '額外技能持續效果時間 (單位:秒)',
  `negativeId` int(10) NOT NULL DEFAULT 0 COMMENT '新增額外負面技能類型(不受距離限制)',
  `negativeTime` int(10) NOT NULL DEFAULT 0 COMMENT '新增額外負面技能時間(不受距離限制) (單位:秒)',
  `attr` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '傷害附加屬性 (0:無, 1:地, 2:火, 4:水, 8:風, 16:光)',
  `hpAbsorb` int(10) NOT NULL DEFAULT 0 COMMENT '吸血量',
  `mpAbsorb` int(10) NOT NULL DEFAULT 0 COMMENT '吸魔量',
  PRIMARY KEY (`item_id`) USING BTREE
) ENGINE = MyISAM CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of extra_weapon_skill
