-- ----------------------------
-- Table structure for mobskill
-- ----------------------------
DROP TABLE IF EXISTS `mobskill`;
CREATE TABLE `mobskill`  (
  `mobid` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `actNo` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `mobname` varchar(45) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '',
  `Type` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '1:物理 2:魔法 3:召喚 4:變身 5:群暈 6:群消 7:群壞',
  `TriRnd` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '發動機率(%)',
  `TriHp` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT 'HP條件發動(HP低於設定值)',
  `TriCompanionHp` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '同族HP條件發動(同族HP低於設定值)',
  `TriRange` int(10) NOT NULL DEFAULT 0 COMMENT '設定值小於0 則小於設定距離(轉正整數)發動技能,設定值大於0 則超出設定距離發動技能',
  `TriCount` int(10) NOT NULL DEFAULT 0 COMMENT '技能發動次數',
  `ChangeTarget` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '技能發動時目標判定 1:目前攻擊者 2:目前攻擊自己的對象 3:範圍目標',
  `Range` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '攻擊距離(物理攻擊設置)物理攻擊必須設定1以上',
  `AreaWidth` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '攻擊範圍(物理攻擊設置)單體攻擊設置0,範圍攻擊必須設定1以上',
  `AreaHeight` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '攻擊範圍(物理攻擊設置)單體攻擊設置0,範圍攻擊必須設定1以上',
  `Leverage` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '攻擊倍率(1/10)',
  `SkillId` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '對應魔法技能編號',
  `Gfxid` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '對應魔法技能編號',
  `ActId` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '物理攻擊使用的動作編號',
  `SummonId` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '召喚技能使用屬下編號',
  `SummonMin` int(10) NOT NULL DEFAULT 0 COMMENT '召喚最小數量',
  `SummonMax` int(10) NOT NULL DEFAULT 0 COMMENT '召喚最大數量',
  `PolyId` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '強制變身代號',
  `reuseDelay` int(10) NOT NULL DEFAULT 0,
  PRIMARY KEY (`mobid`, `actNo`) USING BTREE
) ENGINE = MyISAM CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of mobskill
-- ----------------------------

