  `agrocoi` tinyint(1) UNSIGNED NOT NULL DEFAULT 0,
  `family` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '',
  `agrofamily` int(1) UNSIGNED NOT NULL DEFAULT 0,
