  `change_head` int(1) NOT NULL DEFAULT 0,
  `cant_resurrect` tinyint(1) UNSIGNED NOT NULL DEFAULT 0,
  `quest_score` int(10) NOT NULL DEFAULT 0,
  `is_broadcast` tinyint(1) NULL DEFAULT 0 COMMENT '擊殺公告(1=公告0=不公告)',
  `DropGround` tinyint(1) NOT NULL DEFAULT 0 COMMENT '怪物死亡物品掉落地面範圍(設0不掉落地面)',
  `WeaponSoulExp` int(3) NOT NULL DEFAULT 0 COMMENT '玩家殺死後給多少劍靈值(設0不給劍靈值)',
  PRIMARY KEY (`npcid`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 40701107 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of npc
-- ----------------------------

-- ----------------------------
-- Table structure for npc_box
-- ----------------------------
DROP TABLE IF EXISTS `npc_box`;
CREATE TABLE `npc_box`  (
  `npcid` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '寶箱NpcId編號',
  `note` varchar(45) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '' COMMENT '註解用',
  `needKeyId` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '開啟寶箱需要的鑰匙道具編號',
  `resetTimeSecsMin` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '寶箱重置最短時間 (單位:秒)',
  `resetTimeSecsMax` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '寶箱重置最長時間 (單位:秒)',
  `createItemChances` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '' COMMENT '開出寶物的道具機率列表 (可用逗號區隔) 機率必須由低往高-不能重複-最後面的機率設100',
  `createItemIds` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '' COMMENT '開出寶物的道具編號列表 (可用逗號區隔)',
  `createItemCounts` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '' COMMENT '開出寶物的道具數量列表 (可用逗號區隔)',
  `CreateMobChance` int(10) NOT NULL DEFAULT 0 COMMENT '當有設開出怪物時 多少幾率開出怪物(100%)',
  `mobNpcIdList` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '' COMMENT '開出怪物的NpcId列表 (可用逗號區隔)',
  `MobTime` int(10) NOT NULL DEFAULT 600 COMMENT '出開的怪物存在時間(秒)(0=永久存在)',
  PRIMARY KEY (`npcid`) USING BTREE
) ENGINE = MyISAM CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of npc_box
