-- ----------------------------
-- Table structure for npcaction_teleport
-- ----------------------------
DROP TABLE IF EXISTS `npcaction_teleport`;
CREATE TABLE `npcaction_teleport`  (
  `id` int(10) NOT NULL AUTO_INCREMENT,
  `name` varchar(45) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT '$',
  `orderid` varchar(45) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT 'A',
  `locx` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `locy` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `mapid` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `itemid` int(10) NOT NULL DEFAULT 40308,
  `price` int(10) NOT NULL DEFAULT 0,
  `time` int(10) NOT NULL DEFAULT 0,
  `user` int(10) NOT NULL DEFAULT 0,
  `min` int(10) NOT NULL DEFAULT 0,
  `max` int(10) NOT NULL DEFAULT 10,
  `start_week` tinyint(2) NOT NULL DEFAULT -1 COMMENT '限制星期幾傳送 1~7',
  `start_hour` tinyint(2) NOT NULL DEFAULT -1 COMMENT '限制幾點開始可傳送0~23',
  `end_hour` tinyint(2) NOT NULL DEFAULT -1 COMMENT '限制幾點後結束傳送 0~23',
  `note` varchar(45) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 381 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

