  `out_week` int(2) NOT NULL DEFAULT 0 COMMENT '傳走指定時間-星期1-7(設0不判斷星期)',
  `out_hour` int(2) NOT NULL DEFAULT 0 COMMENT '傳走指定時間-小時',
  `out_minute` int(2) NOT NULL DEFAULT 0 COMMENT '傳走指定時間-分',
  `out_second` int(2) NOT NULL DEFAULT 0 COMMENT '傳走指定時間-秒',
  `back_locx` int(10) NOT NULL DEFAULT 33438 COMMENT '傳回坐標',
  `back_locy` int(10) NOT NULL DEFAULT 32810 COMMENT '傳回坐標',
  `back_mapid` int(10) NOT NULL DEFAULT 4 COMMENT '傳回地圖',
  `back_msg` varchar(45) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '傳回時訊息',
  PRIMARY KEY (`out_mapid`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = latin1 COLLATE = latin1_swedish_ci ROW_FORMAT = Dynamic;

