-- ----------------------------
-- Table structure for reward_clan_skills
-- ----------------------------
DROP TABLE IF EXISTS `reward_clan_skills`;
CREATE TABLE `reward_clan_skills`  (
  `ClanSkillId` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '血盟技能編號',
  `ClanSkillLv` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '血盟技能等級',
  `ClanSkillName` varchar(45) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '' COMMENT '血盟技能名稱',
  `Note` varchar(45) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '效果介紹' COMMENT '效果介紹',
  `Material` varchar(250) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT '' COMMENT '技能所需材料編號 逗號分開',
  `MaterialCount` varchar(250) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT '' COMMENT '技能所需材料數量 逗號分開',
  `MaterialLevel` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT '' COMMENT '技能所需材料等級 逗號分開',
  `CheckLvturn` tinyint(2) UNSIGNED NOT NULL DEFAULT 0 COMMENT '限制幾轉以上享有該效果',
  `CheckLevel` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '限制幾等以上享有該效果',
  `AddMaxHp` int(5) UNSIGNED NOT NULL DEFAULT 0,
  `AddMaxMp` int(5) UNSIGNED NOT NULL DEFAULT 0,
  `AddHpr` tinyint(2) UNSIGNED NOT NULL DEFAULT 0,
  `AddMpr` tinyint(2) UNSIGNED NOT NULL DEFAULT 0,
  `AddStr` tinyint(2) UNSIGNED NOT NULL DEFAULT 0,
  `AddCon` tinyint(2) UNSIGNED NOT NULL DEFAULT 0,
  `AddDex` tinyint(2) UNSIGNED NOT NULL DEFAULT 0,
  `AddInt` tinyint(2) UNSIGNED NOT NULL DEFAULT 0,
  `AddWis` tinyint(2) UNSIGNED NOT NULL DEFAULT 0,
  `AddCha` tinyint(2) UNSIGNED NOT NULL DEFAULT 0,
  `ReductionDmg` tinyint(3) UNSIGNED NOT NULL DEFAULT 0,
  `ReductionMagicDmg` tinyint(3) UNSIGNED NOT NULL DEFAULT 0,
  `AddWater` tinyint(2) UNSIGNED NOT NULL DEFAULT 0,
  `AddWind` tinyint(2) UNSIGNED NOT NULL DEFAULT 0,
  `AddAc` tinyint(2) UNSIGNED NOT NULL DEFAULT 0,
  `AddSp` tinyint(2) UNSIGNED NOT NULL DEFAULT 0,
  `AddMr` tinyint(2) UNSIGNED NOT NULL DEFAULT 0,
  `AddDmg` tinyint(2) UNSIGNED NOT NULL DEFAULT 0,
  `AddBowDmg` tinyint(2) UNSIGNED NOT NULL DEFAULT 0,
  `AddHit` tinyint(2) UNSIGNED NOT NULL DEFAULT 0,
  `AddBowHit` tinyint(2) UNSIGNED NOT NULL DEFAULT 0,
  `AddFire` tinyint(2) UNSIGNED NOT NULL DEFAULT 0,
  `AddEarth` tinyint(2) UNSIGNED NOT NULL DEFAULT 0,
  PRIMARY KEY (`ClanSkillId`, `ClanSkillLv`) USING BTREE
) ENGINE = MyISAM CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

