-- ----------------------------
-- Table structure for server_castle_war_gift
-- ----------------------------
DROP TABLE IF EXISTS `server_castle_war_gift`;
CREATE TABLE `server_castle_war_gift`  (
  `castle_id` int(10) NOT NULL DEFAULT 0 COMMENT '城堡編號',
  `note` varchar(250) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '說明',
  `itemid` int(10) NOT NULL DEFAULT 0 COMMENT '給予獎勵物品編號',
  `count` int(10) NOT NULL DEFAULT 1 COMMENT '給予獎勵物品數量',
  `recover` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '該物品是否回收 0:不回收 1:回收',
  `ac` int(2) NOT NULL DEFAULT 0,
  `hp` int(5) NOT NULL DEFAULT 0,
  `mp` int(5) NOT NULL DEFAULT 0,
  `hpr` int(5) NOT NULL DEFAULT 0,
  `mpr` int(5) NOT NULL DEFAULT 0,
  `str` int(2) NOT NULL DEFAULT 0,
  `con` int(2) NOT NULL DEFAULT 0,
  `dex` int(2) NOT NULL DEFAULT 0,
  `wis` int(2) NOT NULL DEFAULT 0,
  `cha` int(2) NOT NULL DEFAULT 0,
  `intel` int(2) NOT NULL DEFAULT 0,
  `sp` int(5) NOT NULL DEFAULT 0,
  `mr` int(5) NOT NULL DEFAULT 0,
  `hit_modifier` int(5) NOT NULL DEFAULT 0 COMMENT '近戰攻擊命中',
  `dmg_modifier` int(5) NOT NULL DEFAULT 0 COMMENT '近戰攻擊傷害',
  `bow_hit_modifier` int(5) NOT NULL DEFAULT 0 COMMENT '遠距攻擊命中',
  `bow_dmg_modifier` int(5) NOT NULL DEFAULT 0 COMMENT '遠距攻擊傷害',
  `magic_dmg_modifier` int(5) NOT NULL DEFAULT 0 COMMENT '額外魔法傷害',
  `defense_water` int(2) NOT NULL DEFAULT 0,
  `defense_wind` int(2) NOT NULL DEFAULT 0,
  `defense_fire` int(2) NOT NULL DEFAULT 0,
  `defense_earth` int(2) NOT NULL DEFAULT 0,
  `gfx` int(10) NOT NULL DEFAULT 0 COMMENT '效特',
  `time` int(10) NOT NULL DEFAULT 0,
  PRIMARY KEY (`castle_id`, `itemid`) USING BTREE,
  INDEX `castle_id`(`castle_id`) USING BTREE
) ENGINE = MyISAM CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

