-- ----------------------------
-- Table structure for server_fishing
-- ----------------------------
DROP TABLE IF EXISTS `server_fishing`;
CREATE TABLE `server_fishing`  (
  `fish_itemid` int(11) NOT NULL DEFAULT 0 COMMENT '魚竿編號',
  `fish_time` int(10) NOT NULL DEFAULT 60 COMMENT '釣魚時間(勿設低於10秒)(相同魚竿時間請設一樣)',
  `note` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT '' COMMENT '備註',
  `give_itemid` int(10) NOT NULL DEFAULT 0 COMMENT '釣到的物品編號',
  `give_count` int(10) NOT NULL DEFAULT 1 COMMENT '釣到的物品數量',
  `random` int(10) NOT NULL DEFAULT 1000 COMMENT '機率(百萬)',
  `fail_itemid` int(10) NOT NULL DEFAULT 0 COMMENT '釣魚失敗給予的物品編號(0=不給)',
  `fail_count` int(10) NOT NULL DEFAULT 1 COMMENT '釣魚失敗給予的物品數量',
  `fish_gfx` int(10) NOT NULL DEFAULT 0 COMMENT '釣魚成功特效編號(0=沒有)',
  `show_world` tinyint(1) NOT NULL DEFAULT 0 COMMENT '釣魚成功是否公告(0否,1是)',
  PRIMARY KEY (`fish_itemid`, `give_itemid`) USING BTREE,
  INDEX `id`(`give_itemid`) USING BTREE
) ENGINE = MyISAM CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

