-- ----------------------------
-- Table structure for server_item_power
-- ----------------------------
DROP TABLE IF EXISTS `server_item_power`;
CREATE TABLE `server_item_power`  (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT '水號(序號)',
  `power_id` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '0' COMMENT '對應server_item_power_name內的power_id',
  `note` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '明說',
  `msg` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '完成套裝要出現的文字',
  `ac` int(2) NOT NULL DEFAULT 0 COMMENT '防禦',
  `hp` int(5) NOT NULL DEFAULT 0 COMMENT '血量',
  `mp` int(5) NOT NULL DEFAULT 0 COMMENT '魔量',
  `hpr` int(5) NOT NULL DEFAULT 0 COMMENT '回血量',
  `mpr` int(5) NOT NULL DEFAULT 0 COMMENT '回魔量',
  `str` int(5) NOT NULL DEFAULT 0 COMMENT '力量',
  `con` int(5) NOT NULL DEFAULT 0 COMMENT '體質',
  `dex` int(5) NOT NULL DEFAULT 0 COMMENT '敏捷',
  `cha` int(5) NOT NULL DEFAULT 0 COMMENT '魅力',
  `int` int(5) NOT NULL DEFAULT 0 COMMENT '智力',
  `wis` int(5) NOT NULL DEFAULT 0 COMMENT '精神',
  `mr` int(5) NOT NULL DEFAULT 0 COMMENT '魔防',
  `sp` int(2) NOT NULL DEFAULT 0 COMMENT '魔攻',
  `hit` int(2) NOT NULL DEFAULT 0 COMMENT '物理命中',
  `dmgup` int(2) NOT NULL DEFAULT 0 COMMENT '物理攻擊',
  `bowhit` int(2) NOT NULL DEFAULT 0 COMMENT '弓的命中',
  `bowdmgup` int(2) NOT NULL DEFAULT 0 COMMENT '弓的攻擊',
  `dice_dmg` int(2) NOT NULL DEFAULT 0 COMMENT '機率給予爆擊 ',
  `dmg` int(2) NOT NULL DEFAULT 0 COMMENT '機率給予爆擊質',
  `dodge` int(2) NOT NULL DEFAULT 0 COMMENT '迴避攻擊',
  `dice_hp` int(2) NOT NULL DEFAULT 0 COMMENT '機率-吸血',
  `sucking_hp` int(2) NOT NULL DEFAULT 0 COMMENT '機率-吸血質',
  `dice_mp` int(2) NOT NULL DEFAULT 0 COMMENT '機率-吸魔',
  `sucking_mp` int(2) NOT NULL DEFAULT 0 COMMENT '機率-吸魔質',
  `double_dmg` int(2) NOT NULL DEFAULT 0 COMMENT '機率發動加倍的攻擊力',
  `lift` int(2) NOT NULL DEFAULT 0 COMMENT '機率可以將對方的武防裝備解除',
  `defense_water` int(2) NOT NULL DEFAULT 0,
  `defense_wind` int(2) NOT NULL DEFAULT 0,
  `defense_fire` int(2) NOT NULL DEFAULT 0,
  `defense_earth` int(2) NOT NULL DEFAULT 0,
  `weaponMD` int(2) NOT NULL DEFAULT 0 COMMENT '增加魔武傷害',
  `weaponMDC` int(2) NOT NULL DEFAULT 0 COMMENT '增加魔武機率',
  `reducedmg` int(2) NOT NULL DEFAULT 0 COMMENT '物理減免',
  `reduceMdmg` int(2) NOT NULL DEFAULT 0 COMMENT '魔法減免',
  `gfx` varchar(45) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '動畫特效編號設定',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `id`(`id`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 911 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of server_item_power
-- ----------------------------

