  `dice` int(10) NOT NULL DEFAULT 10,
  PRIMARY KEY (`power_id`) USING BTREE,
  INDEX `id`(`power_id`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 49546 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

