  `toid` int(10) NOT NULL DEFAULT 0 COMMENT '可升級的物品ITEMID',
  `needids` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '40308' COMMENT '升級需要消耗的物品',
