-- ----------------------------
-- Table structure for server_mary
-- ----------------------------
DROP TABLE IF EXISTS `server_mary`;
CREATE TABLE `server_mary`  (
  `id` int(10) NOT NULL AUTO_INCREMENT,
  `all_stake` bigint(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '累積賭注',
  `all_user_prize` bigint(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '累積中獎金額',
  `out_prize` int(10) NOT NULL DEFAULT 80 COMMENT '輸出獎金百分比',
  `item_id` int(10) NOT NULL DEFAULT 40308 COMMENT '需要下注的物品編號',
  `count` int(10) UNSIGNED NOT NULL DEFAULT 1 COMMENT '已使用次數',
  `x_a1` int(10) NOT NULL DEFAULT 100 COMMENT '大BAR',
  `x_a2` int(10) NOT NULL DEFAULT 50 COMMENT '小BAR',
  `x_b1` int(10) NOT NULL DEFAULT 40 COMMENT '大半瓜',
  `x_b2` int(10) NOT NULL DEFAULT 2 COMMENT '小半瓜',
  `x_c1` int(10) NOT NULL DEFAULT 30 COMMENT '大蘋果',
  `x_c2` int(10) NOT NULL DEFAULT 2 COMMENT '小蘋果',
  `x_d1` int(10) NOT NULL DEFAULT 20 COMMENT '大西瓜',
  `x_d2` int(10) NOT NULL DEFAULT 2 COMMENT '小西瓜',
  `x_e1` int(10) NOT NULL DEFAULT 15 COMMENT '大香蕉',
  `x_e2` int(10) NOT NULL DEFAULT 2 COMMENT '小香蕉',
  `x_f1` int(10) NOT NULL DEFAULT 10 COMMENT '大檸檬',
  `x_f2` int(10) NOT NULL DEFAULT 2 COMMENT '小檸檬',
  `x_g1` int(10) NOT NULL DEFAULT 5 COMMENT '大橘子',
  `x_g2` int(10) NOT NULL DEFAULT 2 COMMENT '小橘子',
  `note` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '備註',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `id`(`id`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 2 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

