-- ----------------------------
-- Table structure for server_quest
-- ----------------------------
DROP TABLE IF EXISTS `server_quest`;
CREATE TABLE `server_quest`  (
  `id` int(10) NOT NULL AUTO_INCREMENT,
  `questname` varchar(45) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '$' COMMENT '任務NAMEID',
  `questclass` varchar(45) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT '0',
  `queststart` tinyint(1) NOT NULL DEFAULT 0 COMMENT '任務是否啟用',
  `del` tinyint(1) NOT NULL DEFAULT 0 COMMENT '任務是否可以刪除',
  `questuser` int(10) NULL DEFAULT 1024 COMMENT '可執行職業',
  `questlevel` int(10) NOT NULL DEFAULT 1024 COMMENT '可執行等級',
  `difficulty` int(10) NULL DEFAULT 1 COMMENT '任務難度(必須執行的過程數量)',
  `x` int(255) NOT NULL,
  `y` int(255) NOT NULL,
  `mapid` int(255) NOT NULL,
  `item` int(255) NOT NULL,
  `count` int(255) NOT NULL,
  `windows` int(10) NOT NULL,
  `note` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT '說明:',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `id`(`id`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 1081 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of server_quest
-- ----------------------------

