-- Table structure for server_quest_maps
-- ----------------------------
DROP TABLE IF EXISTS `server_quest_maps`;
CREATE TABLE `server_quest_maps`  (
  `mapid` int(10) NOT NULL DEFAULT 0,
  `time` int(10) NOT NULL DEFAULT -1 COMMENT '該地圖可進入時間限制 單位:秒(-1無限制)',
  `users` int(10) NOT NULL DEFAULT 8 COMMENT '允許一次進入人數(-1無限制)',
  `note` varchar(45) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  PRIMARY KEY (`mapid`, `time`) USING BTREE
) ENGINE = MyISAM CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of server_quest_maps
-- ----------------------------

-- ----------------------------
-- Table structure for server_quest_mob
-- ----------------------------
DROP TABLE IF EXISTS `server_quest_mob`;
CREATE TABLE `server_quest_mob`  (
  `quest_id` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '任務編號',
  `quest_step` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '任務進度',
  `note` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT '' COMMENT '備註/說明',
  `lv` int(3) NOT NULL DEFAULT 0 COMMENT '需要等級',
  `npc_gfxid` int(10) NOT NULL DEFAULT 0 COMMENT '任務怪物顯示特效(設0不顯示)',
  `mob_id` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT '' COMMENT '怪物編號 可\",\"號隔開',
  `mob_count` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT '' COMMENT '怪物數量 可\",\"號隔開',
  `item_id` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT '' COMMENT '獎勵編號 可\",\"號隔開',
  `item_lv` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT '' COMMENT '獎勵等級 可\",\"號隔開',
  `item_count` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT '' COMMENT '獎勵數量 可\",\"號隔開',
  `save_quest_step` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '儲存任務進度',
  `tele_x` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '完成任務後傳送做標x',
  `tele_y` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '完成任務後傳送做標y',
  `tele_m` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '完成任務後傳送地圖',
  `tele_delay` int(10) UNSIGNED NOT NULL DEFAULT 0,
  PRIMARY KEY (`quest_id`, `quest_step`) USING BTREE,
  INDEX `id`(`quest_id`) USING BTREE
) ENGINE = MyISAM CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

