-- ----------------------------
-- Table structure for skills
-- ----------------------------
DROP TABLE IF EXISTS `skills`;
CREATE TABLE `skills`  (
  `skill_id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `name` varchar(45) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '',
  `skill_level` int(10) NOT NULL DEFAULT 0,
  `skill_number` int(10) NOT NULL DEFAULT 0,
  `mpConsume` int(10) UNSIGNED NOT NULL DEFAULT 5,
  `hpConsume` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `itemConsumeId` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `itemConsumeCount` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `reuseDelay` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `buffDuration` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `target` varchar(45) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '',
  `target_to` int(10) NOT NULL DEFAULT 0 COMMENT '施展對象 0:自己 1:玩家 2:NPC 4:血盟 8:隊伍 16:寵物 32:位置',
  `damage_value` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '魔法基礎傷害',
  `damage_dice` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '魔法基礎傷害隨機附加值',
  `damage_dice_count` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '魔法基礎傷害隨機附加值 附加次數',
  `probability_value` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '技能基礎機率',
  `probability_dice` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '技能計算機率',
  `attr` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '魔法屬性 0.無屬性魔法,1.地屬性魔法,2.火屬性魔法,4.水屬性魔法,8.風屬性魔法,16.光屬性魔法',
  `type` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '魔法種類 1:破壞 2:輔助 4:詛咒 8:死亡 16:治療 32:復活 64:攻擊 128:其他特殊',
  `lawful` int(10) NOT NULL DEFAULT 0,
  `ranged` int(10) NOT NULL DEFAULT 0 COMMENT '施放距離',
  `area` int(10) NOT NULL DEFAULT 0 COMMENT '技能範圍',
  `through` int(10) NOT NULL DEFAULT 0,
  `id` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `nameid` varchar(45) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '',
  `action_id` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `castgfx` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `castgfx2` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `sysmsgID_happen` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `sysmsgID_stop` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `sysmsgID_fail` int(10) UNSIGNED NOT NULL DEFAULT 0,
  PRIMARY KEY (`skill_id`) USING BTREE,
  INDEX `skill_id`(`skill_id`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 929294 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = 'MyISAM free: 10240 kB; MyISAM free: 10240 kB' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of skills
-- ----------------------------

