) ENGINE = MyISAM AUTO_INCREMENT = 41529 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = 'MyISAM free: 10240 kB; MyISAM free: 10240 kB' ROW_FORMAT = Dynamic;

