-- ----------------------------
-- Table structure for skills_pc_probability
-- ----------------------------
DROP TABLE IF EXISTS `skills_pc_probability`;
CREATE TABLE `skills_pc_probability`  (
  `skill_id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '技能編號(只支持在L1MagicPc設置的機率技能,只支持對玩家施放的技能,放在此表除耐性扣機率外將完全按照此表的設置)',
  `name` varchar(45) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '',
  `是否啟用` tinyint(1) NOT NULL DEFAULT 1 COMMENT '是否啟用設置(0=不啟用,1=啟用)',
  `小於被打者` int(10) NOT NULL DEFAULT 1 COMMENT '攻擊者等級小於被攻擊者等級時機率(不能設0,最低設1)',
  `等於被打者` int(10) NOT NULL DEFAULT 1 COMMENT '攻擊者等級等於被攻擊者等級時機率(不能設0,最低設1)',
  `高於被打者` int(10) NOT NULL DEFAULT 1 COMMENT '攻擊者等級高於被攻擊者等級時機率(不能設0,最低設1)',
  `智力加百分比` int(10) NOT NULL DEFAULT 0 COMMENT '設0不判斷(設1機率加自身智力除以1, 設2除2)',
  `智力加上限` int(10) NOT NULL DEFAULT 0 COMMENT '設0不判斷,設10限制機率上限最高為10',
  `魔法命中加百分比` int(10) NOT NULL DEFAULT 0 COMMENT '設0不判斷(設1機率加自身魔法命中除以1, 設2除2)',
  `幾轉開始加` int(10) NOT NULL DEFAULT 0 COMMENT '攻擊者幾轉開始加額外機率,設0不判斷',
  `幾轉加多少` int(10) NOT NULL DEFAULT 0 COMMENT '攻擊者幾轉加多少機率,設0不判斷',
  `啟用技術命中` tinyint(1) NOT NULL DEFAULT 0 COMMENT '攻擊者的技術命中是否加機率(0=不加,1=加)',
  `啟用精靈命中` tinyint(1) NOT NULL DEFAULT 0 COMMENT '攻擊者的精靈命中是否加機率(0=不加,1=加)',
  `啟用龍屬命中` tinyint(1) NOT NULL DEFAULT 0 COMMENT '攻擊者的龍屬命中是否加機率(0=不加,1=加)',
  `啟用恐怖命中` tinyint(1) NOT NULL DEFAULT 0 COMMENT '攻擊者的恐怖命中是否加機率(0=不加,1=加)',
  `被打者魔防扣機率百分比` int(10) NOT NULL DEFAULT 0 COMMENT '設0不判斷(設1機率扣除被攻擊者魔防除以1,設2除2)',
  `被打者啟用技術耐性` tinyint(1) NOT NULL DEFAULT 0 COMMENT '被攻擊者的技術耐性是否減機率(0=不減,1=減)',
  `被打者啟用精靈耐性` tinyint(1) NOT NULL DEFAULT 0 COMMENT '被攻擊者的精靈耐性是否減機率(0=不減,1=減)',
  `被打者啟用龍屬耐性` tinyint(1) NOT NULL DEFAULT 0 COMMENT '被攻擊者的龍屬耐性是否減機率(0=不減,1=減)',
  `被打者啟用恐怖耐性` tinyint(1) NOT NULL DEFAULT 0 COMMENT '被攻擊者的恐怖耐性是否減機率(0=不減,1=減)',
  PRIMARY KEY (`skill_id`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 200023 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = 'MyISAM free: 10240 kB; MyISAM free: 10240 kB' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of skills_pc_probability
-- ----------------------------

