DROP TABLE IF EXISTS `spawnlist_boss`;
CREATE TABLE `spawnlist_boss`  (
  `id` int(10) NOT NULL AUTO_INCREMENT,
  `location` varchar(45) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '',
  `broadcastInfo` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '公告說明',
  `isBroadcast` tinyint(1) NULL DEFAULT 0 COMMENT '是否公告',
  `count` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `npc_templateid` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `group_id` int(10) UNSIGNED NOT NULL DEFAULT 0,
