-- ----------------------------
-- Table structure for weapon
-- ----------------------------
DROP TABLE IF EXISTS `weapon`;
CREATE TABLE `weapon`  (
  `item_id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `name` varchar(45) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '',
  `exp_point` int(5) NOT NULL DEFAULT 0,
  `use_camp` int(5) NOT NULL DEFAULT 0 COMMENT '1-A.2-B.4-C.7-共用',
  `MeteLevel` int(10) NULL DEFAULT 0 COMMENT '轉生使用判斷(設置1代表1轉以上才可使用)',
  `MeteLevelMAX` int(10) NULL DEFAULT 10,
  `classname` varchar(45) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '0',
  `name_id` varchar(45) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '',
  `type` varchar(45) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '',
  `material` varchar(45) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '',
  `weight` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `invgfx` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `grdgfx` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `itemdesc_id` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `dmg_small` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `dmg_large` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `range` int(10) NOT NULL DEFAULT 0,
  `safenchant` int(10) NOT NULL DEFAULT 0,
  `use_royal` int(2) UNSIGNED NOT NULL DEFAULT 0,
  `use_knight` int(2) UNSIGNED NOT NULL DEFAULT 0,
  `use_mage` int(2) UNSIGNED NOT NULL DEFAULT 0,
  `use_elf` int(2) UNSIGNED NOT NULL DEFAULT 0,
  `use_darkelf` int(2) UNSIGNED NOT NULL DEFAULT 0,
  `use_dragonknight` int(2) UNSIGNED NOT NULL DEFAULT 0,
  `use_illusionist` int(2) UNSIGNED NOT NULL DEFAULT 0,
  `use_warrior` int(2) UNSIGNED NOT NULL DEFAULT 0,
  `hitmodifier` int(10) NOT NULL DEFAULT 0,
  `dmgmodifier` int(10) NOT NULL DEFAULT 0,
  `add_str` int(10) NOT NULL DEFAULT 0,
  `add_con` int(10) NOT NULL DEFAULT 0,
  `add_dex` int(10) NOT NULL DEFAULT 0,
  `add_int` int(10) NOT NULL DEFAULT 0,
  `add_wis` int(10) NOT NULL DEFAULT 0,
  `add_cha` int(10) NOT NULL DEFAULT 0,
  `add_hp` int(10) NOT NULL DEFAULT 0,
  `add_mp` int(10) NOT NULL DEFAULT 0,
  `add_hpr` int(10) NOT NULL DEFAULT 0,
  `add_mpr` int(10) NOT NULL DEFAULT 0,
  `add_sp` int(10) NOT NULL DEFAULT 0,
  `m_def` int(10) NOT NULL DEFAULT 0,
  `haste_item` int(2) UNSIGNED NOT NULL DEFAULT 0,
  `double_dmg_chance` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `magicdmgmodifier` int(10) NOT NULL DEFAULT 0,
  `canbedmg` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `min_lvl` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `max_lvl` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `bless` int(2) UNSIGNED NOT NULL DEFAULT 1,
  `trade` int(2) UNSIGNED NOT NULL DEFAULT 0,
  `cant_delete` int(2) UNSIGNED NOT NULL DEFAULT 0,
  `max_use_time` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `rankIndex` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '神武排行',
  `stunlvl` int(10) NOT NULL DEFAULT 0 COMMENT '衝暈等級',
  `pvp_dmg` int(2) NOT NULL DEFAULT 0 COMMENT '增加PVP傷害',
  `pvp_dmg_reduction` int(2) NOT NULL DEFAULT 0 COMMENT 'PVP傷害減免',
  `技術耐性` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '技術耐性',
  `精靈耐性` int(10) NOT NULL DEFAULT 0 COMMENT '精靈耐性',
  `龍屬耐性` int(10) NOT NULL DEFAULT 0 COMMENT '龍屬耐性',
  `恐怖耐性` int(10) NOT NULL DEFAULT 0 COMMENT '恐怖耐性',
  `全部耐性` int(10) NOT NULL DEFAULT 0 COMMENT '全部耐性',
  `技術命中` int(10) NOT NULL DEFAULT 0 COMMENT '技術命中',
  `精靈命中` int(10) NOT NULL DEFAULT 0 COMMENT '精靈命中',
  `龍屬命中` int(10) NOT NULL DEFAULT 0 COMMENT '龍屬命中',
  `恐怖命中` int(10) NOT NULL DEFAULT 0 COMMENT '恐怖命中',
  `全部命中` int(10) NOT NULL DEFAULT 0 COMMENT '全部命中',
  `魔法暴擊` int(10) NOT NULL DEFAULT 0 COMMENT '全部命中',
  `is_penetrate` int(1) NOT NULL DEFAULT 0 COMMENT '是否貫通效果(0否,1是)(效果:無視hard=1的硬皮怪物防禦力額外傷害減低)',
  `antiDamageReduction` int(3) NOT NULL DEFAULT 0 COMMENT '無視玩家傷害減免值',
  `einConsumeReduce` int(3) NOT NULL DEFAULT 0 COMMENT '殷海薩祝福消耗減少率(%)目前效果為玩家有殷海薩祝福情況下，1點祝福消耗率為額外加1%經驗',
  `item_xf` int(5) NOT NULL DEFAULT 0,
  `近距離暴擊傷害` int(2) NOT NULL DEFAULT 0 COMMENT '傷害*倍率(100=10倍)=傷害',
  `近距離暴擊倍率` int(2) NOT NULL DEFAULT 0 COMMENT '傷害*倍率(100=10倍)=傷害',
  `遠距離暴擊傷害` int(2) NOT NULL DEFAULT 0 COMMENT '傷害*倍率(100=10倍)=傷害',
  `遠距離暴擊倍率` int(2) NOT NULL DEFAULT 0 COMMENT '傷害*倍率(100=10倍)=傷害',
  `近距離迴避率` int(2) NOT NULL DEFAULT 0,
  `遠距離迴避率` int(2) NOT NULL DEFAULT 0,
  `magic_hit_modifier` int(10) NOT NULL DEFAULT 0 COMMENT '魔法命中',
  `發動幾率` int(2) NOT NULL DEFAULT 0 COMMENT '近/遠暴擊倍率-最高100%',
  `降低對怪傷害` int(10) NOT NULL DEFAULT 0 COMMENT '降低對怪傷害',
  `降低對人傷害` int(10) NOT NULL DEFAULT 0 COMMENT '降低對人傷害',
  PRIMARY KEY (`item_id`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 1500015 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = 'MyISAM free: 26624 kB; MyISAM free: 26624 kB; MyISAM free: 3' ROW_FORMAT = Dynamic;

