  `arrow_type` int(11) UNSIGNED NOT NULL DEFAULT 0,
  `attr` int(11) UNSIGNED NOT NULL DEFAULT 0,
  `effect_id1` int(11) NOT NULL,
  `effect_target1` int(11) NOT NULL,
  `effect_xy1` int(11) NOT NULL,
  `effect_id2` int(11) NOT NULL,
  `effect_target2` int(11) NOT NULL,
  `effect_xy2` int(11) NOT NULL,
  `effect_id3` int(11) NOT NULL,
  `effect_target3` int(11) NOT NULL,
  `effect_xy3` int(11) NOT NULL,
  `effect_id4` int(11) NOT NULL,
  `effect_target4` int(11) NOT NULL,
  `effect_xy4` int(11) NOT NULL,
  `x_str` varchar(5) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '0.00' COMMENT '傷害額外+自身力量x設定值',
  `x_con` varchar(5) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '0.00' COMMENT '傷害額外+自身體質x設定值',
  `x_dex` varchar(5) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '0.00' COMMENT '傷害額外+自身敏捷x設定值',
  `x_int` varchar(5) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '0.00' COMMENT '傷害額外+自身智力x設定值',
  `x_wis` varchar(5) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '0.00' COMMENT '傷害額外+自身精神x設定值',
  `x_cha` varchar(5) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '0.00' COMMENT '傷害額外+自身魅力x設定值',
  `x_sp` varchar(5) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '0.00' COMMENT '傷害額外+自身魔攻x設定值',
  `r_str` varchar(5) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '0.00' COMMENT '傷害額外+隨機->自身力量x設定值',
  `r_con` varchar(5) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '0.00' COMMENT '傷害額外+隨機->自身體質x設定值',
  `r_dex` varchar(5) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '0.00' COMMENT '傷害額外+隨機->自身敏捷x設定值',
  `r_int` varchar(5) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '0.00' COMMENT '傷害額外+隨機->自身智力x設定值',
  `r_wis` varchar(5) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '0.00' COMMENT '傷害額外+隨機->自身精神x設定值',
  `r_cha` varchar(5) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '0.00' COMMENT '傷害額外+隨機->自身魅力x設定值',
  `r_sp` varchar(5) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '0.00' COMMENT '傷害額外+隨機->自身魔攻x設定值',
  `c_mp` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '吸魔',
  `ran_c_hp` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '吸血',
  PRIMARY KEY (`weapon_id`) USING BTREE
