CREATE TABLE `weapon_skill_power`  (
  `id` int(10) NOT NULL AUTO_INCREMENT COMMENT '序號',
  `classname` varchar(45) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '0',
  `level` int(10) NOT NULL DEFAULT 100 COMMENT '發動等級百分比',
  `type1` int(10) NOT NULL DEFAULT 0,
  `type2` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `type3` int(10) NOT NULL DEFAULT 0,
  `attr` int(10) NOT NULL DEFAULT 0 COMMENT '具備攻擊屬性 0:無属性 1:地 2:火 4:水 8:風',
  `ac_mr` int(10) NOT NULL DEFAULT 0 COMMENT '受到抗魔或是防禦力影響 0:無視 1:防禦 2:抗魔',
  `gfxid1` int(10) NOT NULL DEFAULT 0 COMMENT '設置為0無作用 這個動畫出現在施展者身上',
  `gfxid2` int(10) NOT NULL DEFAULT 0 COMMENT '設置為0無作用 這個動畫出現在被攻擊者身上',
  `gfxid3` int(10) NOT NULL DEFAULT 0 COMMENT '設置為0無作用 這個動畫由施展者往被攻擊者',
  `gfxid4` int(10) NOT NULL DEFAULT 0 COMMENT '設置為0無作用 這個動畫由施展者周邊隨機座標出現指定次數',
  `gfxid4_count` int(10) NOT NULL DEFAULT 0 COMMENT 'GFXID4 指定次數 設置0 GFXID4無作用',
  `power` int(10) NOT NULL DEFAULT 0 COMMENT '受影響人的物屬性 1:力 2:敏 4:智 8:精 16:魅 32:體',
  `srcdmg` int(10) NOT NULL DEFAULT 0 COMMENT '基礎攻擊質(隨機 設定10 隨機質產生1 ~ 10)',
  `addsrcdmg` int(10) NOT NULL DEFAULT 0 COMMENT '是否加入武器產生的物理傷害質(1~100)',
  `random1` int(10) NOT NULL DEFAULT 0 COMMENT '發動機率(1/1000)',
  `random2` int(10) NOT NULL DEFAULT 0 COMMENT '受到強化質的機率影響(1/1000)',
  `boss_holdout` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '設置為1該技能對spawnlist_boss召喚表內怪物不起作用',
  `note` varchar(150) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT '',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `id`(`id`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 54 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of weapon_skill_power
-- ----------------------------

-- ----------------------------
-- Table structure for weapon_soul
-- ----------------------------
DROP TABLE IF EXISTS `weapon_soul`;
CREATE TABLE `weapon_soul`  (
  `weapon_id` int(10) NOT NULL COMMENT '有劍靈系統的武器編號',
  `note` varchar(1000) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '注解',
  `soul_exp_limit` int(10) NOT NULL DEFAULT 3600 COMMENT '打怪獲得的劍靈值上限(超過設置上限,武器不再獲得劍靈值)',
  `soul_min_exp` int(10) NOT NULL DEFAULT 600 COMMENT '最低多少劍靈值才能召喚',
  `soul_gfx_id` int(10) NOT NULL DEFAULT 10884 COMMENT '召喚的劍靈圖檔',
  `soul_level` double(2, 1) NOT NULL DEFAULT 0.7 COMMENT '玩家召喚的劍靈等級倍數(設1等於玩家的等級*1)(可小數)',
  `soul_str` double(2, 1) NOT NULL DEFAULT 0.7 COMMENT '玩家召喚的劍靈力量倍數(設1等於玩家的力量*1)(可小數)',
  `soul_con` double(2, 1) NOT NULL DEFAULT 0.7 COMMENT '玩家召喚的劍靈體質倍數(設1等於玩家的體質*1)(可小數)',
  `soul_dex` double(2, 1) NOT NULL DEFAULT 0.7 COMMENT '玩家召喚的劍靈敏捷倍數(設1等於玩家的敏捷*1)(可小數)',
  `soul_int` double(2, 1) NOT NULL DEFAULT 0.7 COMMENT '玩家召喚的劍靈智力倍數(設1等於玩家的智力*1)(可小數)',
  `soul_wis` double(2, 1) NOT NULL DEFAULT 0.7 COMMENT '玩家召喚的劍靈精神倍數(設1等於玩家的精神*1)(可小數)',
  `soul_mp` int(10) NOT NULL DEFAULT 10 COMMENT '玩家召喚的劍靈魔量',
  `soul_name` varchar(1000) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT '劍靈' COMMENT '玩家召喚的劍靈名字',
  PRIMARY KEY (`weapon_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = latin1 COLLATE = latin1_swedish_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of weapon_soul
-- ----------------------------

-- ----------------------------
-- Table structure for william_comes_monster
-- ----------------------------
DROP TABLE IF EXISTS `william_comes_monster`;
CREATE TABLE `william_comes_monster`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `note` varchar(1024) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT '',
  `type` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '0=怪   1=道具',
  `objid` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '道具編號 or 怪物編號',
  `count` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '數量',
  `mapId` smallint(5) UNSIGNED NOT NULL DEFAULT 0 COMMENT '地圖編號',
  `x` smallint(5) UNSIGNED NOT NULL DEFAULT 0 COMMENT '座標',
  `y` smallint(5) UNSIGNED NOT NULL DEFAULT 0 COMMENT '座標',
  `x_end` smallint(5) UNSIGNED NOT NULL DEFAULT 0 COMMENT '座標',
  `y_end` smallint(5) UNSIGNED NOT NULL DEFAULT 0 COMMENT '座標',
  `Day` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL COMMENT '出現的時間(1=禮拜1   2=禮拜2  以此類推)',
  `Time` time NOT NULL COMMENT '出現的時間',
  `Message` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT '' COMMENT '出現的訊息',
  `SpawnGfxId` smallint(5) UNSIGNED NOT NULL DEFAULT 0 COMMENT '出現的特效',
  `DeleteTime` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '刪除的時間(單位：分)',
  `CycleTime` int(10) NOT NULL DEFAULT -1,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 15 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_unicode_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of william_comes_monster
-- ----------------------------

-- ----------------------------
-- Table structure for william_kinlin_itemblend
-- ----------------------------
DROP TABLE IF EXISTS `william_kinlin_itemblend`;
CREATE TABLE `william_kinlin_itemblend`  (
  `item_id` int(10) NOT NULL,
  `name` varchar(45) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL,
  `checkClass` int(1) NOT NULL DEFAULT 0,
  `checkLevel` int(2) NOT NULL DEFAULT 0,
  `rnd` int(10) NOT NULL DEFAULT 100,
  `checkItem` int(10) NOT NULL DEFAULT 0,
  `hpConsume` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `mpConsume` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `material` int(10) NOT NULL DEFAULT 0,
  `material_count` int(10) NOT NULL DEFAULT 0,
  `material_2` int(10) NOT NULL DEFAULT 0,
  `material_2_count` int(10) NOT NULL DEFAULT 0,
  `material_3` int(10) NOT NULL DEFAULT 0,
  `material_3_count` int(10) NOT NULL DEFAULT 0,
  `material_4` int(10) NOT NULL DEFAULT 0,
  `material_4_count` int(10) NOT NULL DEFAULT 0,
  `material_5` int(10) NOT NULL DEFAULT 0,
  `material_5_count` int(10) NOT NULL DEFAULT 0,
  `new_item` int(10) NOT NULL DEFAULT 0,
  `new_item_counts` int(10) NOT NULL DEFAULT 0,
  `new_Enchantlvl_SW` int(1) NOT NULL DEFAULT 0,
  `new_item_Enchantlvl` int(10) NOT NULL DEFAULT 0,
  `removeItem` int(1) NOT NULL DEFAULT 1,
  `message` varchar(1000) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `item_Html` int(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`item_id`) USING BTREE
) ENGINE = MyISAM CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of william_kinlin_itemblend
-- ----------------------------

-- ----------------------------
-- Table structure for william_limitedreward
-- ----------------------------
DROP TABLE IF EXISTS `william_limitedreward`;
CREATE TABLE `william_limitedreward`  (
  `id` int(10) NOT NULL,
  `note` varchar(1000) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `activity` tinyint(1) NOT NULL DEFAULT 1,
  `check_classId` int(10) NOT NULL DEFAULT 255 COMMENT '領取職業 王族:1 騎士:2  精靈:4 法師:8 黑妖:16 龍騎:32 幻術:64 戰士:128',
  `check_level` int(10) NOT NULL DEFAULT 0,
  `check_item` int(10) NOT NULL DEFAULT 0,
  `check_itemCount` int(10) NOT NULL DEFAULT 0,
  `surplus_msg` varchar(1000) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '字串裡面加入%s(代表：check_itemCount - check_item身上有的數量)的餘額',
  `surplus_msg_color` int(10) NOT NULL DEFAULT -1 COMMENT '白色:14、鐵灰:7、咖啡色:24、黃色:13、粉紅:47、紫色:4、紅色:3、橘色:53、天空藍:10、深海藍:1、深綠:2、草地綠:11',
  `give_item_id` varchar(1000) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `give_itemCount` varchar(1000) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `give_itemEnchantlvl` varchar(1000) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `total_People` bigint(20) NOT NULL DEFAULT 0,
  `appear_People` bigint(20) NOT NULL DEFAULT 0,
  `quest_id` int(5) NOT NULL DEFAULT 0,
  `quest_step` int(5) NOT NULL DEFAULT 0,
  `message` varchar(1000) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '字串裡面加入%s(代表：totalCount - appearCount  - 1)的名額',
  `message_end` varchar(1000) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = MyISAM CHARACTER SET = sjis COLLATE = sjis_japanese_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of william_limitedreward
-- ----------------------------

-- ----------------------------
-- Table structure for william_lv_accessory
-- ----------------------------
DROP TABLE IF EXISTS `william_lv_accessory`;
CREATE TABLE `william_lv_accessory`  (
  `type` int(2) UNSIGNED ZEROFILL NOT NULL DEFAULT 00 COMMENT '8=項鏈,9=戒指,10=腰帶,12=耳環',
  `note` varchar(1000) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `greater` int(2) NOT NULL DEFAULT 0 COMMENT '0:耐性(耳環/項鏈),1:熱情(戒指),2:意志(皮帶)',
  `level` int(2) NOT NULL DEFAULT 0 COMMENT '對應飾品加成(飾品卷最高加成限制在altsettings.properties的EnchantAccessory設置)',
  `addStr` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `addDex` int(3) UNSIGNED NOT NULL DEFAULT 0,
  `addCon` int(3) UNSIGNED NOT NULL DEFAULT 0,
  `addInt` int(3) UNSIGNED NOT NULL DEFAULT 0,
  `addWis` int(3) UNSIGNED NOT NULL DEFAULT 0,
  `addCha` int(3) UNSIGNED NOT NULL DEFAULT 0,
  `addAc` int(3) UNSIGNED NOT NULL DEFAULT 0,
  `addMaxHp` int(5) UNSIGNED NOT NULL DEFAULT 0,
  `addMaxMp` int(5) UNSIGNED NOT NULL DEFAULT 0,
  `addHpr` int(5) UNSIGNED NOT NULL DEFAULT 0,
  `addMpr` int(5) UNSIGNED NOT NULL DEFAULT 0,
  `addDmg` int(5) UNSIGNED NOT NULL DEFAULT 0,
  `addBowDmg` int(5) UNSIGNED NOT NULL DEFAULT 0,
  `addHit` int(3) UNSIGNED NOT NULL DEFAULT 0,
  `addBowHit` int(3) UNSIGNED NOT NULL DEFAULT 0,
  `addDmgReduction` int(5) UNSIGNED NOT NULL DEFAULT 0 COMMENT '全部傷害減免',
  `addMr` int(3) UNSIGNED NOT NULL DEFAULT 0,
  `addSp` int(3) UNSIGNED NOT NULL DEFAULT 0,
  `PVPdmg` int(5) UNSIGNED NOT NULL DEFAULT 0,
  `PVPdmgReduction` int(5) UNSIGNED NOT NULL DEFAULT 0,
  `Potion_Heal` int(5) UNSIGNED NOT NULL DEFAULT 0 COMMENT '增加治愈藥水恢復量(%)',
  `Potion_Healling` int(5) UNSIGNED NOT NULL DEFAULT 0 COMMENT '增加治愈藥水恢復量(指定量)',
  `add_magic_hit` int(5) UNSIGNED NOT NULL DEFAULT 0 COMMENT '增加魔法命中',
  `einConsumeReduce` int(3) NOT NULL DEFAULT 0 COMMENT '殷海薩祝福消耗減少(1=1%)',
  `技術耐性` int(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '技術耐性',
  `精靈耐性` int(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '精靈耐性',
  `龍屬耐性` int(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '龍屬耐性',
  `恐怖耐性` int(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '恐怖耐性',
  `全部耐性` int(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '全部耐性',
  `技術命中` int(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '技術命中',
  `精靈命中` int(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '精靈命中',
  `龍屬命中` int(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '龍屬命中',
  `恐怖命中` int(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '恐怖命中',
  `全部命中` int(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '全部命中',
  PRIMARY KEY (`type`, `level`) USING BTREE
) ENGINE = MyISAM CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of william_lv_accessory
-- ----------------------------

-- ----------------------------
-- Table structure for william_lv_armor_weapon
-- ----------------------------
DROP TABLE IF EXISTS `william_lv_armor_weapon`;
CREATE TABLE `william_lv_armor_weapon`  (
  `itemid` int(10) NOT NULL DEFAULT 0 COMMENT '道具編號[只適用武器-防具(不包括飾品-符文)]',
  `note` varchar(1000) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '注解-說明',
  `enchantlevel` int(2) NOT NULL DEFAULT 0 COMMENT '大於等於多少加成才給能力 如果道具大於裡面設置的最大加成-就讀取設置的最大加成能力',
  `addAc` int(3) NOT NULL DEFAULT 0 COMMENT '額外防禦',
  `addStr` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `addDex` int(3) UNSIGNED NOT NULL DEFAULT 0,
  `addCon` int(3) UNSIGNED NOT NULL DEFAULT 0,
  `addInt` int(3) UNSIGNED NOT NULL DEFAULT 0,
  `addWis` int(3) UNSIGNED NOT NULL DEFAULT 0,
  `addCha` int(3) UNSIGNED NOT NULL DEFAULT 0,
  `addMaxHp` int(5) UNSIGNED NOT NULL DEFAULT 0,
  `addMaxMp` int(5) UNSIGNED NOT NULL DEFAULT 0,
  `addHpr` int(5) UNSIGNED NOT NULL DEFAULT 0,
  `addMpr` int(5) UNSIGNED NOT NULL DEFAULT 0,
  `addDmg` int(5) UNSIGNED NOT NULL DEFAULT 0,
  `addBowDmg` int(5) UNSIGNED NOT NULL DEFAULT 0,
  `addHit` int(3) UNSIGNED NOT NULL DEFAULT 0,
  `addBowHit` int(3) UNSIGNED NOT NULL DEFAULT 0,
  `addDmgReduction` int(5) UNSIGNED NOT NULL DEFAULT 0 COMMENT '所有傷害減免',
  `addMr` int(3) UNSIGNED NOT NULL DEFAULT 0,
  `addSp` int(3) UNSIGNED NOT NULL DEFAULT 0,
  `addFire` int(3) UNSIGNED NOT NULL DEFAULT 0,
  `addWind` int(3) UNSIGNED NOT NULL DEFAULT 0,
  `addEarth` int(3) UNSIGNED NOT NULL DEFAULT 0,
  `addWater` int(3) UNSIGNED NOT NULL DEFAULT 0,
  `addPvpDmg` int(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT 'PVP傷害',
  `addPvpDmg_R` int(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT 'PVP傷害減免',
  `addCloseCri` int(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '近距離爆擊率1=1%',
  `addBowCri` int(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '遠距離爆擊率1=1%',
  `addMagicCri` int(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '魔法爆擊率1=1%',
  `einConsumeReduce` int(3) NOT NULL DEFAULT 0 COMMENT '殷海薩祝福消耗減少(1=1%)',
  `技術耐性` int(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '技術耐性',
  `精靈耐性` int(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '精靈耐性',
  `龍屬耐性` int(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '龍屬耐性',
  `恐怖耐性` int(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '恐怖耐性',
  `全部耐性` int(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '全部耐性',
  `技術命中` int(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '技術命中',
  `精靈命中` int(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '精靈命中',
  `龍屬命中` int(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '龍屬命中',
  `恐怖命中` int(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '恐怖命中',
  `全部命中` int(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '全部命中',
  `魔法命中` int(10) NOT NULL DEFAULT 0 COMMENT '全部命中',
  `antiDamageReduction` int(3) NOT NULL DEFAULT 0 COMMENT '無視玩家傷害減免值',
  PRIMARY KEY (`itemid`, `enchantlevel`) USING BTREE
) ENGINE = MyISAM CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of william_lv_armor_weapon
-- ----------------------------

-- ----------------------------
-- Table structure for william_mob_item
-- ----------------------------
DROP TABLE IF EXISTS `william_mob_item`;
CREATE TABLE `william_mob_item`  (
  `id` int(5) NOT NULL AUTO_INCREMENT COMMENT '無意義(會自動遞增)',
  `npc_id` int(10) NOT NULL COMMENT '怪物編號',
  `name` char(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `checkClass` int(1) NOT NULL DEFAULT 0 COMMENT '判定職業 (0=不判斷,1=王族,2=騎士,3=法師,4=妖精,5=黑妖,6=龍騎,7=幻術,8=戰士)',
  `level` int(2) NOT NULL DEFAULT 0 COMMENT '判定玩家等級',
  `checkItem` int(10) NOT NULL DEFAULT 0 COMMENT '判定需要何種道具',
  `random` int(10) NOT NULL DEFAULT 100 COMMENT '機率(100%)',
  `Kyo` int(1) NOT NULL DEFAULT 0 COMMENT '判斷陣營(0 = 不判斷)',
  `Prestige` int(10) NOT NULL DEFAULT 0 COMMENT '判斷陣營積分(0 = 不判斷)',
  `talk` varchar(1000) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '怪物死亡大喊說的內容(null=不說話)',
  `new_item` varchar(1000) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '給予的道具(多個逗號隔開)(null=不給)',
  `new_item_counts` varchar(1000) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '給予的道具數量',
  `skills` varchar(1000) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '給予的技能(多個逗號隔開)(null=不給技能)',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 65 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of william_mob_item
-- ----------------------------

-- ----------------------------
-- Table structure for william_npc_buff_skill
-- ----------------------------
DROP TABLE IF EXISTS `william_npc_buff_skill`;
CREATE TABLE `william_npc_buff_skill`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `npcid` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT '' COMMENT 'NPC編號',
  `note` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NULL DEFAULT NULL COMMENT '註解',
  `action` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NULL DEFAULT NULL COMMENT '對話執行命令',
  `skills` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NULL DEFAULT NULL COMMENT '輔助魔法編號 多個,隔開 對應times數量',
  `times` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NULL DEFAULT NULL COMMENT '輔助魔法時間 多個,隔開 對應skills數量(懶得設時間就設0=魔法原本時間)',
  `material` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NULL DEFAULT NULL COMMENT '所需道具 多個,隔開 對應material_count數量',
  `material_count` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NULL DEFAULT NULL COMMENT '所需道具數量 多個,隔開 對應material數量',
  `checkClass` int(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '判斷可加魔法輔助職業(1-8,設0不判斷)',
  `checkCamp` int(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '判斷可加魔法輔助陣營(設0不判斷)',
  `checkMinLevel` int(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '判斷可加魔法輔助最低等級(設0不判斷)',
  `checkMaxLevel` int(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '判斷可加魔法輔助最高等級(設0不判斷)',
  `checkTurnLevel` int(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '判斷可加魔法輔助轉生等級(設0不判斷)',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 8 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_unicode_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of william_npc_buff_skill
-- ----------------------------

-- ----------------------------
-- Table structure for william_online_reward
-- ----------------------------
DROP TABLE IF EXISTS `william_online_reward`;
CREATE TABLE `william_online_reward`  (
  `id` int(10) NOT NULL AUTO_INCREMENT,
  `dayWeek` int(2) NOT NULL DEFAULT 0 COMMENT '禮拜1~7幾點',
  `hour` int(2) NOT NULL DEFAULT 0 COMMENT '幾點 24H制',
  `minute` int(10) NOT NULL DEFAULT 0 COMMENT '幾分(會有1分鐘左右誤差)',
  `people` int(10) NOT NULL DEFAULT 0 COMMENT '判斷線上玩家數量多少才開啟抽獎(線上玩家必須大於設置,小於或等於設置不開啟抽獎)',
  `give_item` int(10) NOT NULL DEFAULT 0 COMMENT '給予物品編號',
  `give_count_min` int(10) NOT NULL DEFAULT 0 COMMENT '給予物品最少數量',
  `give_count_max` int(10) NOT NULL DEFAULT 0 COMMENT '給予物品最大數量',
  `check_level` int(10) NOT NULL DEFAULT 0 COMMENT '是否達到等級資格才可獲得',
  `check_lvturn` int(10) NOT NULL DEFAULT 0 COMMENT '是否達到幾轉資格才可獲得',
  `check_prestige` int(10) NOT NULL DEFAULT 0 COMMENT '是否達到陣營積分資格才可獲得',
  `check_mapId` int(10) NOT NULL DEFAULT -1 COMMENT '哪一張地圖的玩家適用於1,5,6,7,8,9,10  -1=全地圖',
  `check_classId` int(10) NOT NULL DEFAULT 255 COMMENT '全職業就是 255',
  `check_VIP` int(10) NOT NULL DEFAULT 0 COMMENT '是否達到VIP資格才可獲得',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 31 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Fixed;

