  `quest_id` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '制作的编号(按前后顺序排列)',
  `quest_step` int(10) NOT NULL DEFAULT 255,
  `note` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT '說明:',
  `addStr` int(10) NOT NULL DEFAULT 0 COMMENT '可執行職業',
  `addDex` int(10) NOT NULL DEFAULT 0 COMMENT '可執行等級',
  `addCon` int(10) NOT NULL DEFAULT 0 COMMENT '任務難度(必須執行的過程數量)',
  `addInt` int(10) NOT NULL DEFAULT 0 COMMENT '可執行職業',
  `addWis` int(10) NOT NULL DEFAULT 0 COMMENT '可執行等級',
  `addCha` int(10) NOT NULL DEFAULT 0 COMMENT '任務難度(必須執行的過程數量)',
  `addMaxHp` int(10) NOT NULL DEFAULT 0 COMMENT '可執行職業',
  `addMaxMp` int(10) NOT NULL DEFAULT 0 COMMENT '可執行等級',
  `addHpr` int(10) NOT NULL DEFAULT 0 COMMENT '任務難度(必須執行的過程數量)',
  `addMpr` int(10) NOT NULL DEFAULT 0 COMMENT '可執行等級',
  `addDmg` int(10) NOT NULL DEFAULT 0 COMMENT '任務難度(必須執行的過程數量)',
  `addBowDmg` int(10) NOT NULL DEFAULT 0 COMMENT '可執行職業',
  `addHit` int(10) NOT NULL DEFAULT 0 COMMENT '可執行等級',
  `addBowHit` int(10) NOT NULL DEFAULT 0 COMMENT '任務難度(必須執行的過程數量)',
  `addDmgReduction` int(10) NOT NULL DEFAULT 0 COMMENT '可執行等級',
  `addMr` int(10) NOT NULL DEFAULT 0 COMMENT '任務難度(必須執行的過程數量)',
  `addSp` int(10) NOT NULL DEFAULT 0 COMMENT '可執行職業',
  `addFire` int(10) NOT NULL DEFAULT 0 COMMENT '可執行等級',
  `addWind` int(10) NOT NULL DEFAULT 0 COMMENT '任務難度(必須執行的過程數量)',
  `addEarth` int(10) NOT NULL DEFAULT 0 COMMENT '可執行等級',
  `addWater` int(10) NOT NULL DEFAULT 0 COMMENT '任務難度(必須執行的過程數量)',
  `addPvpDmg` int(10) NOT NULL DEFAULT 0 COMMENT '任務難度(必須執行的過程數量)',
  `addPvpDmg_R` int(10) NOT NULL DEFAULT 0 COMMENT '任務難度(必須執行的過程數量)',
  `ac` int(10) NOT NULL DEFAULT 0 COMMENT '防禦',
  `up_hp_potion` int(10) NOT NULL DEFAULT 0 COMMENT '喝水',
  `uhp_number` int(10) NOT NULL DEFAULT 0 COMMENT '喝水',
  `近距離暴擊傷害` int(2) NOT NULL DEFAULT 0 COMMENT '傷害*倍率(100=10倍)=傷害',
  `近距離暴擊倍率` int(2) NOT NULL DEFAULT 0 COMMENT '傷害*倍率(100=10倍)=傷害',
  `遠距離暴擊傷害` int(2) NOT NULL DEFAULT 0 COMMENT '傷害*倍率(100=10倍)=傷害',
  `遠距離暴擊倍率` int(2) NOT NULL DEFAULT 0 COMMENT '傷害*倍率(100=10倍)=傷害',
  `近距離迴避率` int(2) NOT NULL DEFAULT 0,
  `遠距離迴避率` int(2) NOT NULL DEFAULT 0,
  `antiDamageReduction` int(3) NOT NULL DEFAULT 0 COMMENT '無視玩家傷害減免值',
  `魔法暴擊` int(2) NOT NULL DEFAULT 0,
  `技術命中` int(2) NOT NULL DEFAULT 0 COMMENT '技術命中',
  `技術耐性` int(2) NOT NULL DEFAULT 0,
  `三重傷害` int(5) NOT NULL DEFAULT 0,
  `究極傷害` int(5) NOT NULL DEFAULT 0,
  INDEX `id`(`quest_id`(10)) USING BTREE
) ENGINE = MyISAM CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

