-- ----------------------------
-- Table structure for 官服任務系統
-- ----------------------------
DROP TABLE IF EXISTS `官服任務系統`;
CREATE TABLE `官服任務系統`  (
  `questid` int(10) NOT NULL AUTO_INCREMENT COMMENT 'quest-common.bin的任務編號',
  `note` varchar(1000) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `是否啟用` tinyint(1) NOT NULL DEFAULT 1 COMMENT '0=關閉,1=開啟',
  `最低等級` int(2) NOT NULL DEFAULT 1,
  `最高等級` int(2) NOT NULL DEFAULT 55,
  `任務地圖` int(10) NOT NULL DEFAULT -1 COMMENT '默認-1等於不判斷玩家所在地圖，其它數字就玩家需在此地圖才會顯示任務',
  `傳送座標` varchar(45) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT '' COMMENT '格式32731,32811,3',
  `固定獎勵編號` varchar(45) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT '',
  `固定獎勵數量` varchar(45) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT '',
  `固定獎勵加成` varchar(45) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT '',
  `選擇獎勵編號` varchar(45) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT '',
  `選擇獎勵數量` varchar(45) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT '',
  `選擇獎勵加成` varchar(45) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT '',
  `獎勵經驗` int(10) NOT NULL DEFAULT 0,
  `判斷職業` varchar(45) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT 'A' COMMENT '全職=A,王=P,騎=K,妖=E,法=W,黑=D,龍=R,幻=I,戰=O',
  `達到等級` int(2) NOT NULL DEFAULT 0,
  `獵殺怪物編號` varchar(45) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT '',
  `獵殺怪物數量` varchar(45) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT '',
  `是否刪除收集道具` tinyint(1) NOT NULL DEFAULT 0,
  `收集道具編號` varchar(45) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT '',
  `收集道具數量` varchar(45) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT '',
  `收集道具加成` varchar(45) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT '',
  `使用道具編號` varchar(45) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT '',
  `使用道具數量` varchar(45) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT '',
  PRIMARY KEY (`questid`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 2922 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

