  `近戰命中` int(3) NOT NULL DEFAULT 0,
  `遠攻攻擊` int(3) NOT NULL DEFAULT 0,
  `遠攻命中` int(3) NOT NULL DEFAULT 0,
  `回血` int(10) NOT NULL DEFAULT 0,
  `回魔` int(10) NOT NULL DEFAULT 0,
