  `item_id` int(10) UNSIGNED NOT NULL COMMENT '道具編號(除娃娃外的其它不可重疊道具)',
  `note` varchar(45) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT '',
  `level` int(2) NOT NULL DEFAULT 0 COMMENT '只能設11-17(需修改PromoteDollUI-c.xml，加入可自動添加11-16的按鈕)',
  PRIMARY KEY (`item_id`) USING BTREE
) ENGINE = MyISAM CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = Dynamic;

